-- D265 data repair: registry snake_case keys folded into the model's keys
-- (generated from REGISTRY_KEY_ALIASES in shared/registry-fields.ts). The model
-- key wins when both exist; blank aliases are simply dropped.
UPDATE profiles SET fields = (CASE WHEN (fields ? 'monthlyAmount') AND fields->>'monthlyAmount' IS NOT NULL AND fields->>'monthlyAmount' <> '' THEN fields ELSE CASE WHEN fields->>'monthly_payment' IS NULL OR fields->>'monthly_payment' = '' THEN fields ELSE fields || jsonb_build_object('monthlyAmount', fields->'monthly_payment') END END) - 'monthly_payment' WHERE fields ? 'monthly_payment';
UPDATE profiles SET fields = (CASE WHEN (fields ? 'minimumPayment') AND fields->>'minimumPayment' IS NOT NULL AND fields->>'minimumPayment' <> '' THEN fields ELSE CASE WHEN fields->>'minimum_payment' IS NULL OR fields->>'minimum_payment' = '' THEN fields ELSE fields || jsonb_build_object('minimumPayment', fields->'minimum_payment') END END) - 'minimum_payment' WHERE fields ? 'minimum_payment';
