UPDATE profiles SET fields = (CASE WHEN (fields ? 'extraPayment') AND fields->>'extraPayment' IS NOT NULL AND fields->>'extraPayment' <> '' THEN fields ELSE CASE WHEN fields->>'extra_payment' IS NULL OR fields->>'extra_payment' = '' THEN fields ELSE fields || jsonb_build_object('extraPayment', fields->'extra_payment') END END) - 'extra_payment' WHERE fields ? 'extra_payment';
