UPDATE profiles SET fields = (CASE WHEN (fields ? 'renewalDate') AND fields->>'renewalDate' IS NOT NULL AND fields->>'renewalDate' <> '' THEN fields ELSE CASE WHEN fields->>'renewal_date' IS NULL OR fields->>'renewal_date' = '' THEN fields ELSE fields || jsonb_build_object('renewalDate', fields->'renewal_date') END END) - 'renewal_date' WHERE fields ? 'renewal_date';
