UPDATE profiles SET fields = fields || jsonb_build_object('nextDueDate', fields->'dueDate') WHERE fields ? 'dueDate' AND NOT (fields ? 'nextDueDate') AND type_key IN (SELECT type_key FROM profile_type_definitions WHERE category = 'subscriptions');
